const I18nContext = createContext<{ language: Language; setLanguage: (l: Language) => void; t: (key: string) => string }>({ language: 'en', setLanguage: () => {}, t: key => key })
function I18nProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    const value = localStorage.getItem('bablex.language')
    return value === 'es' || value === 'pt' || value === 'fr' || value === 'de' ? value : 'en'
  })
  const setLanguage = (next: Language) => { setLanguageState(next); localStorage.setItem('bablex.language', next); document.documentElement.lang = next }
  useEffect(() => { document.documentElement.lang = language }, [language])
  const t = (key: string) => TRANSLATIONS[language][key] || TRANSLATIONS.en[key] || key
  return <I18nContext.Provider value={{ language, setLanguage, t }}>{children}</I18nContext.Provider>
}
function useI18n() { return useContext(I18nContext) }

function EyeIcon({ hidden }: { hidden: boolean }) {
  return hidden ? <svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 3l18 18"/><path d="M10.6 10.6a2 2 0 1 0 2.8 2.8"/><path d="M9.9 4.2A11.8 11.8 0 0 1 12 4c5 0 8.8 4 10 8-0.3 1.1-.9 2.4-1.8 3.5"/><path d="M6.1 6.1C4.4 7.4 3.3 9.2 2 12c1.2 4 5 8 10 8 1.5 0 2.9-.3 4.1-.9"/></svg> : <svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>
}
const LOCAL_SESSION_KEY = 'bablex.local-session'

async function loadConfig() { const r = await fetch('/config.json', { cache: 'no-store' }); if (!r.ok) throw new Error('Unable to load configuration'); return r.json() as Promise<RuntimeConfig> }
function createAuth(c: RuntimeConfig) { const s: UserManagerSettings = { authority: c.cognitoAuthority, client_id: c.cognitoClientId, redirect_uri: c.redirectUri, post_logout_redirect_uri: c.logoutUri, response_type: 'code', scope: 'openid email profile', userStore: new WebStorageStateStore({ store: localStorage }) }; return new UserManager(s) }
async function bootstrap() { const c = await loadConfig(); if (c.mode === 'local') { ReactDOM.createRoot(document.getElementById('root')!).render(<I18nProvider><LocalApp config={c} /></I18nProvider>); return }; const auth = createAuth(c); if (location.pathname === '/auth/callback') { await auth.signinCallback(); history.replaceState({}, document.title, '/') }; const user = await auth.getUser(); ReactDOM.createRoot(document.getElementById('root')!).render(<I18nProvider><AwsApp config={c} auth={auth} initialUser={user} /></I18nProvider>) }

function AwsApp({ config, auth, initialUser }: { config: RuntimeConfig; auth: UserManager; initialUser: User | null }) { const [user, setUser] = useState(initialUser); useEffect(() => { auth.getUser().then(setUser) }, [auth]); if (!user) return <Landing onLogin={() => void auth.signinRedirect()} label="Sign in / Create account" />; const api: Api = async (path, init = {}) => { const u = await auth.getUser(); const token = u?.id_token || u?.access_token; if (!token) throw new Error('Session expired'); const h = new Headers(init.headers); h.set('Authorization', `Bearer ${token}`); if (init.body) h.set('Content-Type', 'application/json'); const r = await fetch(config.apiBaseUrl + path, { ...init, headers: h }); if (r.status === 204) return null; const p = await r.json().catch(() => ({})); if (!r.ok) throw new Error(p.error || 'Request failed'); return p }; return <AppShell api={api} mode="aws" onLogout={async () => { await auth.removeUser(); try { await auth.signoutRedirect() } catch { location.href = config.logoutUri } }} /> }
function LocalApp({ config }: { config: RuntimeConfig }) { const { t } = useI18n(); const [session, setSession] = useState<LocalSession | null>(() => loadLocalSession()); const [view, setView] = useState<'login' | 'signup'>('login'); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [showPassword, setShowPassword] = useState(false); const [error, setError] = useState(''); if (session) return <AppShell api={createLocalApi(config.apiBaseUrl, session)} mode="local" onLogout={() => { localStorage.removeItem(LOCAL_SESSION_KEY); setSession(null) }} />; const submit = async (e: React.FormEvent) => { e.preventDefault(); setError(''); const r = await fetch(`${config.apiBaseUrl}/auth/${view === 'login' ? 'login' : 'signup'}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password }) }); const p = await r.json().catch(() => ({})); if (!r.ok) { setError(p.error || 'Authentication failed'); return }; if (view === 'signup') { setView('login'); setPassword(''); setShowPassword(false); return }; const next = normalizeLocalSession(p); persistLocalSession(next); setSession(next) }; const switchView = () => { setView(view === 'login' ? 'signup' : 'login'); setPassword(''); setShowPassword(false); setError('') }; return <main className="center page-shell"><section className="card auth-card"><div className="brand-mark">L</div><p className="eyebrow">BABLEX · LOCAL</p><h1>{t(view === 'login' ? 'Welcome back.' : 'Create your account.')}</h1>{error && <div className="alert">{error}</div>}<form onSubmit={submit} className="auth-form"><label>{t('Email')}<input type="email" required value={email} onChange={e => setEmail(e.target.value)} /></label><label>{t('Password')}<div className="password-field"><input type={showPassword ? 'text' : 'password'} minLength={8} required value={password} onChange={e => setPassword(e.target.value)} /><button type="button" className="password-eye" onClick={() => setShowPassword(togglePasswordVisibility)} aria-label={t(showPassword ? 'Hide password' : 'Show password')} title={t(showPassword ? 'Hide password' : 'Show password')}><EyeIcon hidden={!showPassword} /></button></div></label><button className="primary full">{t(view === 'login' ? 'Sign in' : 'Create account')}</button></form><button className="link-button" onClick={switchView}>{t(view === 'login' ? 'Need an account? Create one' : 'Already have an account? Sign in')}</button></section></main> }

function AppShell({ api, mode, onLogout }: { api: Api; mode: 'local' | 'aws'; onLogout: () => void }) {
  const { t, language, setLanguage } = useI18n()
  const languageInitialized = useRef(false)
  const [page, setPage] = useState<'books' | 'libraries' | 'authors' | 'categories' | 'profile'>('books')
  const [libraries, setLibraries] = useState<LibraryInfo[]>([])
  const [selectedLibrary, setSelectedLibrary] = useState('all')
  const [profile, setProfile] = useState<Profile | null>(null)
  const [menu, setMenu] = useState(false)
  const [shellError, setShellError] = useState('')
  const refresh = async () => {
    setShellError('')
    const results = await Promise.allSettled([api('/libraries'), api('/me')])
    const librariesResult = results[0]
    const profileResult = results[1]
    if (librariesResult.status === 'fulfilled') setLibraries(librariesResult.value.items || [])
    else setShellError(String(librariesResult.reason))
    if (profileResult.status === 'fulfilled') { setProfile(profileResult.value); if (!languageInitialized.current && profileResult.value.preferredLanguage) { setLanguage(profileResult.value.preferredLanguage); languageInitialized.current = true } }
    else setShellError(current => current || String(profileResult.reason))
  }
  useEffect(() => { void refresh() }, [])
  const headingKey = page === 'books' ? 'My books' : page === 'libraries' ? 'Libraries' : page === 'authors' ? 'Authors' : page === 'categories' ? 'Categories' : 'My account'
  const heading = t(headingKey)
  const changeAppLanguage = async (next: Language) => {
    setLanguage(next)
    if (!profile) return
    try {
      const updated = await api('/me', { method: 'PATCH', body: JSON.stringify({ ...profile, preferredLanguage: next }) })
      setProfile(updated)
    } catch (err) {
      setShellError(String(err))
    }
  }
  return <main className="page-shell"><header className="topbar"><div><p className="eyebrow">BABLEX</p><h1>{heading}</h1></div><div className="top-actions"><span className="user-email">{profile?.email || ''}</span><select className="language-picker" value={language} onChange={e => void changeAppLanguage(e.target.value as Language)} aria-label="Language" title={LANGUAGE_LABELS[language]}>{LANGUAGE_OPTIONS.map(option => <option key={option.code} value={option.code}>{option.text}</option>)}</select><div className="menu-wrap"><button className="secondary" onClick={() => setMenu(!menu)}>Menu ▾</button>{menu && <div className="card menu"><button onClick={() => { setPage('books'); setMenu(false) }}>{t('Books')}</button><button onClick={() => { setPage('libraries'); setMenu(false) }}>{t('Libraries')}</button><button onClick={() => { setPage('authors'); setMenu(false) }}>{t('Authors')}</button><button onClick={() => { setPage('categories'); setMenu(false) }}>{t('Categories')}</button><button onClick={() => { setPage('profile'); setMenu(false) }}>{t('Personal data')}</button><hr /><button className="danger-text" onClick={onLogout}>{t('Sign out')}</button></div>}</div></div></header>{shellError && <div className="alert">{shellError}</div>}{page === 'books' && <BooksPage api={api} libraries={libraries} selected={selectedLibrary} setSelected={setSelectedLibrary} />}{page === 'libraries' && <LibrariesPage api={api} libraries={libraries} refresh={refresh} />}{page === 'authors' && <AuthorsPage api={api} />}{page === 'categories' && <CategoriesPage api={api} />}{page === 'profile' && <ProfilePage api={api} profile={profile || { id: '', email: '' }} mode={mode} onSaved={setProfile} />}</main>
}

function BooksPage({ api, libraries, selected, setSelected }: { api: Api; libraries: LibraryInfo[]; selected: string; setSelected: (x: string) => void }) {
  const { t } = useI18n()
  const [books, setBooks] = useState<Book[]>([])
  const [authors, setAuthors] = useState<Author[]>([])
  const [categories, setCategories] = useState<Category[]>([])
  const [query, setQuery] = useState('')
  const [view, setView] = useState<'cards' | 'table'>('cards')
  const [editing, setEditing] = useState<Book | null>(null)
  const [details, setDetails] = useState<Book | null>(null)
  const [show, setShow] = useState(false)
  const [error, setError] = useState('')
  const refresh = async () => {
    try {
      setError('')
      const [a, c] = await Promise.all([api('/authors'), api('/categories')])
      setAuthors(a.items || []); setCategories(c.items || [])
      const source = selected === 'all' ? [...libraries.filter(l => !l.isShared), ...libraries.filter(l => l.isShared)] : libraries.filter(l => l.id === selected)
      const grouped: Book[] = []
      for (const l of source) {
        const r = await api(`/libraries/${l.id}/books`)
        grouped.push(...(r.items || []).map((b: Book) => ({ ...b, libraryId: l.id, libraryName: l.name, isShared: !!l.isShared, sharedOwnerEmail: l.isShared ? l.ownerEmail : '' })))
      }
      setBooks(grouped)
    } catch (e) { setError(String(e)) }
  }
  useEffect(() => { void refresh() }, [selected, libraries.length])
  const filtered = sortBooksForDisplay(books.filter(b => `${b.title} ${b.author || ''} ${b.category || ''} ${b.libraryName || ''}`.toLowerCase().includes(query.toLowerCase())))
  const changeReaction = async (book: Book, next: '' | 'like' | 'dislike') => {
    if (!book.libraryId) return
    await api(`/libraries/${book.libraryId}/books/${book.id}`, { method: 'PATCH', body: JSON.stringify({ reaction: next }) })
    await refresh()
  }
  const saveBook = async (input: Book) => {
    const targetLibrary = input.libraryId
    if (!targetLibrary) throw new Error('Please choose a library')
    const payload: any = { ...input }; delete payload.libraryId; delete payload.libraryName; delete payload.isShared
    if (!editing) {
      await api(`/libraries/${targetLibrary}/books`, { method: 'POST', body: JSON.stringify(payload) })
    } else if (editing.libraryId !== targetLibrary) {
      await api(`/libraries/${editing.libraryId}/books/${editing.id}/move`, { method: 'POST', body: JSON.stringify({ targetLibraryId: targetLibrary }) })
      if (selected !== 'all') setSelected(targetLibrary)
    } else {
      await api(`/libraries/${targetLibrary}/books/${editing.id}`, { method: 'PATCH', body: JSON.stringify(payload) })
    }
    setShow(false); await refresh()
  }
  const renderBookActions = (b: Book) => b.isShared ? <div className="book-actions"><button className="secondary full" onClick={() => setDetails(b)}>Details</button></div> : <div className="book-actions"><button className="secondary" onClick={() => { setEditing(b); setShow(true) }}>Edit</button><button className="danger" onClick={async () => { if (!b.libraryId || !confirm(t('Delete this book?'))) return; try { await api(`/libraries/${b.libraryId}/books/${b.id}`, { method: 'DELETE' }); await refresh(); window.location.reload() } catch (e) { setError(String(e)) } }}>Delete</button></div>
  const renderLibrary = (b: Book) => {
    const library = libraries.find(l => l.id === b.libraryId)
    return <div className="book-library-meta">{b.libraryName}{b.isShared && <span className="shared-tag" style={{ backgroundColor: SHARED_RESOURCE_BACKGROUND }}>{sharedTagLabel(b.sharedOwnerEmail || libraries.find(l => l.id === b.libraryId)?.ownerEmail)}</span>}</div>
  }
  const cardClass = (b: Book) => `card book-card ${b.isShared ? 'shared-book-card' : ''}`
  return <>
    <section className="toolbar card">
      <LibraryPicker libraries={libraries} selected={selected} onChange={setSelected} />
      <input value={query} onChange={e => setQuery(e.target.value)} placeholder={t('Search by title, author, category...')} />
      <div className="view-toggle"><button className={view === 'cards' ? 'active' : ''} onClick={() => setView('cards')} aria-label={t('Card view')}>▦</button><button className={view === 'table' ? 'active' : ''} onClick={() => setView('table')} aria-label={t('Table view')}>☷</button></div>
      <button className="primary" onClick={() => { setEditing(null); setShow(true) }}>{t('+ Add book')}</button>
    </section>
    {error && <div className="alert">{error}</div>}
    {view === 'cards' ? <section className="book-grid">{filtered.map(b => <article className={cardClass(b)} key={`${b.libraryId}-${b.id}`}><div className="book-card-top"><div>{b.isShared && <span className="shared-tag" style={{ backgroundColor: SHARED_RESOURCE_BACKGROUND }}>{sharedTagLabel(b.sharedOwnerEmail || libraries.find(l => l.id === b.libraryId)?.ownerEmail)}</span>}<span className="pill">{b.category || t('Uncategorized')}</span></div><span className="status">{t(capitalizeStatus(b.status))}</span></div><h2>{b.title}</h2><p className="author">{b.author || t('No author')}</p>{renderLibrary(b)}<p className="meta">{t('Registered')} {formatDisplayDate(b.registeredAt || b.createdAt)}{b.publishedAt ? ` · ${t('Published')} ${formatDisplayDate(b.publishedAt)}` : ''}{b.language ? ` · ${t('Language')}: ${languageLabel(b.language)}` : ''}</p><p className="notes">{b.notes || t('No notes')}</p>{!b.isShared && <div className="reaction-bar"><button className={`reaction ${b.reaction === 'like' ? 'selected-like' : ''}`} onClick={() => void changeReaction(b, b.reaction === 'like' ? '' : 'like')} aria-label="Like book">👍</button><button className={`reaction ${b.reaction === 'dislike' ? 'selected-dislike' : ''}`} onClick={() => void changeReaction(b, b.reaction === 'dislike' ? '' : 'dislike')} aria-label="Dislike book">👎</button></div>}{renderBookActions(b)}</article>)}</section> : <div className="card table-wrap"><table><thead><tr><th>{t('Title')}</th><th>{t('Author')}</th><th>{t('Library')}</th><th>{t('Category')}</th><th>{t('Status')}</th><th>{t('Registered')}</th><th>{t('Published')}</th><th>{t('Language')}</th><th>{t('Reaction')}</th><th></th></tr></thead><tbody>{filtered.map(b => <tr key={`${b.libraryId}-${b.id}`} className={b.isShared ? 'shared-book-row' : ''}><td>{b.title}</td><td>{b.author || '-'}</td><td>{b.libraryName}{b.isShared && <span className="shared-tag" style={{ backgroundColor: SHARED_RESOURCE_BACKGROUND }}>{sharedTagLabel(b.sharedOwnerEmail || libraries.find(l => l.id === b.libraryId)?.ownerEmail)}</span>}</td><td>{b.category || '-'}</td><td>{t(capitalizeStatus(b.status))}</td><td>{formatDisplayDate(b.registeredAt || b.createdAt)}</td><td>{formatDisplayDate(b.publishedAt)}</td><td>{b.language ? languageLabel(b.language) : '-'}</td><td><span className="reaction-cell">{b.reaction === 'like' ? '👍' : b.reaction === 'dislike' ? '👎' : '—'}</span></td><td>{b.isShared ? <button className="ghost" onClick={() => setDetails(b)}>Details</button> : <><button className="ghost" onClick={() => { setEditing(b); setShow(true) }}>Edit</button><button className="ghost danger-text" onClick={async () => { if (!b.libraryId || !confirm(t('Delete this book?'))) return; try { await api(`/libraries/${b.libraryId}/books/${b.id}`, { method: 'DELETE' }); await refresh(); window.location.reload() } catch (e) { setError(String(e)) } }}>Delete</button></>}</td></tr>)}</tbody></table></div>}
    {!filtered.length && <section className="card empty"><div className="empty-icon">◌</div><h2>{t('No books found')}</h2><p className="muted">{t('Try another library or search term.')}</p></section>}
    {show && <BookForm api={api} initial={editing} authors={authors} categories={categories} libraries={libraries.filter(l => !l.isShared)} onCancel={() => setShow(false)} onSave={saveBook} />}
    {details && <BookDetails api={api} book={details} onClose={() => setDetails(null)} />}
  </>
}

function LibraryPicker({ libraries, selected, onChange }: { libraries: LibraryInfo[]; selected: string; onChange: (x: string) => void }) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const current = libraries.find(l => l.id === selected)
  return <div className="library-picker">
    <button type="button" className="library-picker-button" onClick={() => setOpen(x => !x)} aria-haspopup="listbox" aria-expanded={open}>
      <span>{selected === 'all' ? t('All Libraries') : current?.name || t('Select library')}</span><span>▾</span>
    </button>
    {open && <div className="card library-picker-menu" role="listbox">
      <button type="button" className={selected === 'all' ? 'active' : ''} onClick={() => { onChange('all'); setOpen(false) }}><strong>{t('All Libraries')}</strong></button>
      {libraries.map(l => <button type="button" key={l.id} className={selected === l.id ? 'active' : ''} onClick={() => { onChange(l.id); setOpen(false) }}><strong>{l.name}</strong>{l.isShared && <small>{libraryOptionSubtitle(l)}</small>}</button>)}
    </div>}
  </div>
}

function ReferenceCombobox({ label, value, selectedId, options, onChange }: { label: string; value: string; selectedId?: string; options: Array<{ id: string; name: string }>; onChange: (name: string, id: string) => void }) { const [open, setOpen] = useState(false); const filtered = useMemo(() => { const q = value.trim().toLowerCase(); return options.filter(o => !q || o.name.toLowerCase().includes(q)).slice(0, 8) }, [options, value]); return <label className="combobox-label">{label}<div className="combobox"><input value={value} onFocus={() => setOpen(true)} onChange={e => { const next = e.target.value; onChange(next, selectedId && options.find(o => o.id === selectedId)?.name?.toLowerCase() === next.trim().toLowerCase() ? selectedId : ''); setOpen(true) }} onBlur={() => window.setTimeout(() => setOpen(false), 120)} placeholder={`Type ${label.toLowerCase()}...`} autoComplete="off" />{open && <div className="combobox-menu card">{filtered.map(o => <button type="button" key={o.id} onMouseDown={e => e.preventDefault()} onClick={() => { onChange(o.name, o.id); setOpen(false) }}>{o.name}</button>)}{value.trim() && !options.some(o => o.name.toLowerCase() === value.trim().toLowerCase()) && <div className="combobox-new">Create “{value.trim()}” when the book is saved</div>}{!filtered.length && !value.trim() && <div className="combobox-new">Start typing to search</div>}</div>}</div></label> }

function CommentsSection({ api, book }: { api: Api; book: Book }) {
  const { t } = useI18n()
  const [comments, setComments] = useState<Comment[]>([])
  const [text, setText] = useState('')
  const [error, setError] = useState('')
  const [saving, setSaving] = useState(false)

  const refresh = async () => {
    if (!book.libraryId) return
    try {
      const data = await api(`/libraries/${book.libraryId}/books/${book.id}/comments`)
      setComments(data.items || [])
      setError('')
    } catch (e) {
      setError(String(e))
    }
  }

  useEffect(() => { void refresh() }, [book.libraryId, book.id])

  const save = async () => {
    if (!book.libraryId || !text.trim() || saving) {
      if (!text.trim()) setError(t('Comment text is required'))
      return
    }
    setSaving(true)
    setError('')
    try {
      const created = await api(`/libraries/${book.libraryId}/books/${book.id}/comments`, {
        method: 'POST',
        body: JSON.stringify({ text: text.trim() })
      })
      setComments(prev => [created, ...prev])
      setText('')
    } catch (e) {
      setError(String(e))
    } finally {
      setSaving(false)
    }
  }

  return <section className="comments-section">
    <h3>{t('Comments')}</h3>
    <div className="comment-compose">
      <textarea rows={3} value={text} onChange={e => setText(e.target.value)} placeholder={t('Write a comment...')} />
      <button className="primary" onClick={() => void save()} disabled={!text.trim() || saving}>
        {saving ? t('Saving...') : t('Save comment')}
      </button>
    </div>
    {error && <div className="alert">{error}</div>}
    {comments.length ? <div className="comment-feed">
      {comments.map(c => <article className="comment-card" key={c.id}>
        <div className="comment-avatar" aria-hidden="true">{(c.userName || c.userEmail || '?').trim().charAt(0).toUpperCase()}</div>
        <div className="comment-body">
          <div className="comment-meta"><strong>{c.userName || c.userEmail}</strong><time dateTime={c.createdAt}>{new Date(c.createdAt).toLocaleString()}</time></div>
          <p>{c.text}</p>
        </div>
      </article>)}
    </div> : <p className="muted">{t('No comments yet.')}</p>}
  </section>
}
function BookDetails({ api, book, onClose }: { api: Api; book: Book; onClose: () => void }) {
  const { t } = useI18n()
  return <div className="modal-backdrop"><section className="card modal details-modal"><div className="modal-header"><div><p className="eyebrow">{book.isShared ? 'SHARED BOOK' : 'BOOK'}</p><h2>{book.title}</h2></div><button className="close" onClick={onClose}>×</button></div><div className="details-grid"><div><span>{t('Author')}</span><strong>{book.author || t('No author')}</strong></div><div><span>{t('Category')}</span><strong>{book.category || t('Uncategorized')}</strong></div><div><span>{t('Library')}</span><strong>{book.libraryName || '-'}</strong></div><div><span>{t('Status')}</span><strong>{book.status}</strong></div><div><span>{t('Registered')}</span><strong>{formatDisplayDate(book.registeredAt || book.createdAt)}</strong></div><div><span>{t('Published')}</span><strong>{formatDisplayDate(book.publishedAt)}</strong></div><div><span>{t('Bought date')}</span><strong>{formatDisplayDate(book.boughtAt)}</strong></div><div><span>{t('Read date')}</span><strong>{formatDisplayDate(book.readAt)}</strong></div><div><span>{t('Language')}</span><strong>{book.language ? languageLabel(book.language) : '-'}</strong></div></div>{book.sharedOwnerEmail && <div className="shared-detail-tag">Shared: {book.sharedOwnerEmail}</div>}{book.notes && <><h3>{t('Notes')}</h3><p className="muted">{book.notes}</p></>}<CommentsSection api={api} book={book} /><div className="form-actions"><button className="primary" onClick={onClose}>{t('Close')}</button></div></section></div>
}

function BookForm({ api, initial, authors, categories, libraries, onCancel, onSave }: { api: Api; initial: Book | null; authors: Author[]; categories: Category[]; libraries: LibraryInfo[]; onCancel: () => void; onSave: (x: Book) => Promise<void> }) {
  const { t } = useI18n()
  const [form, setForm] = useState<any>({ title: initial?.title || '', authorId: initial?.authorId || '', author: initial?.author || '', isbn: initial?.isbn || '', categoryId: initial?.categoryId || '', category: initial?.category || '', status: initial?.status || 'owned', notes: initial?.notes || '', boughtAt: initial?.boughtAt || '', readAt: initial?.readAt || '', publishedAt: initial?.publishedAt || '', language: initial?.language || 'en', reaction: initial?.reaction || '', libraryId: initial?.libraryId || libraries[0]?.id || '' })
  const [error, setError] = useState('')
  const set = (k: string, v: string) => setForm((x: any) => ({ ...x, [k]: v }))
  const submit = async (e: React.FormEvent) => { e.preventDefault(); setError(''); try { await onSave(form) } catch (err) { setError(err instanceof Error ? err.message : String(err)) } }
  return <div className="modal-backdrop"><form className="card modal" onSubmit={submit}><div className="modal-header"><div><p className="eyebrow">{t(initial ? 'EDIT BOOK' : 'NEW BOOK')}</p><h2>{t(initial ? 'Update book' : 'Add a book')}</h2></div><button type="button" className="close" onClick={onCancel}>×</button></div>
    <label>{t('Title')}<input required value={form.title} onChange={e => set('title', e.target.value)} /></label>
    <div className="form-row"><label>{t('Library')}<select required value={form.libraryId} onChange={e => set('libraryId', e.target.value)}><option value="">Select a library</option>{libraries.map(l => <option key={l.id} value={l.id}>{l.name}{libraryOptionSubtitle(l) ? ` - ${libraryOptionSubtitle(l)}` : ''}</option>)}</select></label><label>{t('Language')}<select value={form.language} onChange={e => set('language', e.target.value)} aria-label={t('Language')}>{LANGUAGE_OPTIONS.map(option => <option key={option.code} value={option.code}>{option.text} - {LANGUAGE_LABELS[option.code]}</option>)}</select></label></div>
    <ReferenceCombobox label={t('Author')} value={form.author} selectedId={form.authorId} options={authors} onChange={(name, id) => { set('author', name); set('authorId', id) }} />
    <ReferenceCombobox label={t('Category')} value={form.category} selectedId={form.categoryId} options={categories} onChange={(name, id) => { set('category', name); set('categoryId', id) }} />
    <div className="form-row"><label>{t('ISBN')}<input value={form.isbn} onChange={e => set('isbn', e.target.value)} /></label><label>{t('Status')}<select value={form.status} onChange={e => set('status', e.target.value)}><option value="owned">{t('Owned')}</option><option value="reading">{t('Reading')}</option><option value="read">{t('Read')}</option><option value="wishlist">{t('Wishlist')}</option><option value="lent">{t('Lent')}</option><option value="sold">{t('Sold')}</option><option value="donated">{t('Donated')}</option></select></label></div>
    <div className="form-row"><label>{t('Bought date')}<input type="date" value={form.boughtAt} onChange={e => set('boughtAt', e.target.value)} /></label><label>{t('Read date')}<input type="date" value={form.readAt} onChange={e => set('readAt', e.target.value)} /></label><label>{t('Published date')}<input type="date" value={form.publishedAt} onChange={e => set('publishedAt', e.target.value)} /></label></div>
    <label>{t('Reaction')}<div className="reaction-toggle"><button type="button" className={`reaction-toggle-button ${form.reaction === 'like' ? 'selected-like' : ''}`} onClick={() => set('reaction', form.reaction === 'like' ? '' : 'like')}>{'👍 ' + t('Like')}</button><button type="button" className={`reaction-toggle-button ${form.reaction === 'dislike' ? 'selected-dislike' : ''}`} onClick={() => set('reaction', form.reaction === 'dislike' ? '' : 'dislike')}>{'👎 ' + t('Dislike')}</button></div></label>
    <label>{t('Notes')}<textarea rows={3} value={form.notes} onChange={e => set('notes', e.target.value)} /></label>
    {initial && <CommentsSection api={api} book={initial} />}
    {error && <div className="alert">{error}</div>}
    <p className="fine">{t('Author and category are optional. Existing references are reused; a new value is created only when the book is saved.')}</p>
    <div className="form-actions"><button type="button" className="secondary" onClick={onCancel}>{t('Cancel')}</button><button type="submit" className="primary">{t(initial ? 'Save changes' : 'Save book')}</button></div>
  </form></div>
}

function LibrariesPage({ api, libraries, refresh }: { api: Api; libraries: LibraryInfo[]; refresh: () => Promise<void> }) {
  const { t } = useI18n()
  const [edit, setEdit] = useState<LibraryInfo | null>(null)
  const [access, setAccess] = useState<any[]>([])
  const [email, setEmail] = useState('')
  const [error, setError] = useState('')
  const [saved, setSaved] = useState('')
  const load = async (l: LibraryInfo) => { setError(''); setSaved(''); setEdit(l); try { setAccess((await api(`/libraries/${l.id}/access`)).items || []) } catch (e) { setError(String(e)) } }
  const save = async () => {
    if (!edit) return
    setError(''); setSaved('')
    try {
      const result = edit.id ? await api(`/libraries/${edit.id}`, { method: 'PATCH', body: JSON.stringify({ name: edit.name, description: edit.description || '' }) }) : await api('/libraries', { method: 'POST', body: JSON.stringify({ name: edit.name, description: edit.description || '' }) })
      await refresh(); if (!edit.id && result?.id) await load(result); else setEdit(result); setSaved('Library saved.')
    } catch (e) { setError(String(e)) }
  }
  const ownLibraries = libraries.filter(l => !l.isShared)
  const sharedLibraries = libraries.filter(l => l.isShared)
  const renderCard = (l: LibraryInfo) => <button className={`card list-card ${l.isShared ? 'shared-library-card' : ''}`} key={l.id} onClick={() => void load(l)}>{l.isShared && <small className="shared-owner">{l.ownerEmail}</small>}<strong>{l.name}</strong><span>{l.description || 'No description'}</span>{l.isShared && <span className="shared-tag">Shared: {l.ownerEmail}</span>}</button>
  return <div className="split"><section><button className="primary section-button" onClick={() => { setError(''); setSaved(''); setEdit({ id: '', name: '', description: '', ownerId: '', ownerEmail: '' }); setAccess([]) }}>{t('+ Register library')}</button>{ownLibraries.length > 0 && <h3 className="group-title">{t('My libraries')}</h3>}{ownLibraries.map(renderCard)}{sharedLibraries.length > 0 && <h3 className="group-title shared-section-title">{t('Shared with me')}</h3>}{sharedLibraries.map(renderCard)}</section>{edit && <section className={`card panel ${edit.isShared ? 'shared-library-card' : ''}`}>{edit.isShared && <small className="shared-owner">{edit.ownerEmail}</small>}<h2>{t(edit.id ? 'Library information' : 'New library')}</h2>{error && <div className="alert">{error}</div>}{saved && <div className="success">{saved}</div>}<label>{t('Name')}<input value={edit.name} onChange={e => setEdit({ ...edit, name: e.target.value })} disabled={!!edit.isShared} /></label><label>{t('Description')}<textarea rows={3} value={edit.description || ''} onChange={e => setEdit({ ...edit, description: e.target.value })} disabled={!!edit.isShared} /></label>{!edit.isShared && <button className="primary" onClick={() => void save()}>{t('Save library')}</button>}{edit.id && !edit.isShared && <><hr /><h3>{t('Share library')}</h3><div className="inline"><input type="email" placeholder="reader@example.com" value={email} onChange={e => setEmail(e.target.value)} /><button className="secondary" onClick={async () => { try { await api(`/libraries/${edit.id}/share`, { method: 'POST', body: JSON.stringify({ email }) }); setEmail(''); setAccess((await api(`/libraries/${edit.id}/access`)).items || []); await refresh(); setSaved('Library shared.') } catch (e) { setError(String(e)) } }}>{t('Share')}</button></div><h3>{t('Users with access')}</h3><div className="table-wrap"><table><thead><tr><th>{t('Email')}</th><th>{t('Role')}</th><th></th></tr></thead><tbody>{access.filter(x => x.email && x.email.includes('@')).map(x => <tr key={x.email}><td>{x.email}</td><td>{x.role}</td><td>{x.role !== 'owner' && edit?.id && <button type="button" className="ghost danger-text" title={t('Remove access')} onClick={async () => { if (!confirm(t('Remove access from this library?'))) return; try { await api(`/libraries/${edit.id}/share`, { method: 'DELETE', body: JSON.stringify({ email: x.email }) }); setAccess((await api(`/libraries/${edit.id}/access`)).items || []); await refresh(); setSaved('Library access removed.') } catch (e) { setError(String(e)) } }}>{'🗑'}</button>}</td></tr>)}</tbody></table></div></>}</section>}</div>
}

function AuthorsPage({ api }: { api: Api }) { const { t } = useI18n(); const [authors, setAuthors] = useState<Author[]>([]); const [selected, setSelected] = useState<Author | null>(null); const [books, setBooks] = useState<Book[]>([]); const [query, setQuery] = useState(''); const [view, setView] = useState<'cards' | 'table'>('cards'); const refresh = async () => setAuthors((await api('/authors')).items); useEffect(() => { void refresh() }, []); const choose = async (a: Author) => { setSelected(a); const source: LibraryInfo[] = (await api('/libraries')).items || []; const all: Book[] = []; for (const l of source) { const p = await api(`/libraries/${l.id}/books`); all.push(...p.items.filter((b: Book) => b.authorId === a.id).map((b: Book) => ({ ...b, libraryName: l.name }))) } setBooks(all) }; const visible = authors.filter(a => `${a.name} ${a.country || ''}`.toLowerCase().includes(query.toLowerCase())); return <div><section className="toolbar card"><input value={query} onChange={e => setQuery(e.target.value)} placeholder={t('Search authors...')} /><div className="view-toggle"><button className={view === 'cards' ? 'active' : ''} onClick={() => setView('cards')}>▦</button><button className={view === 'table' ? 'active' : ''} onClick={() => setView('table')}>☷</button></div></section><div className="split"><section>{view === 'cards' ? visible.map(a => <button className="card list-card" key={a.id} onClick={() => void choose(a)}><strong>{a.name}</strong><span>{a.country || t('Country not set')}</span></button>) : <div className="card table-wrap"><table><thead><tr><th>{t('Author')}</th><th>{t('Country')}</th><th>{t('Birth date')}</th></tr></thead><tbody>{visible.map(a => <tr key={a.id} onClick={() => void choose(a)}><td>{a.name}</td><td>{a.country || '-'}</td><td>{formatDisplayDate(a.birthDate)}</td></tr>)}</tbody></table></div>}</section>{selected && <section className="card panel"><h2>{t('Edit author')}</h2><label>{t('Name')}<input value={selected.name} onChange={e => setSelected({ ...selected, name: e.target.value })} /></label><div className="form-row"><label>{t('Country')}<input value={selected.country || ''} onChange={e => setSelected({ ...selected, country: e.target.value })} /></label><label>{t('Birth date')}<input type="date" value={selected.birthDate || ''} onChange={e => setSelected({ ...selected, birthDate: e.target.value })} /></label></div><button className="primary" onClick={async () => { const x = await api(`/authors/${selected.id}`, { method: 'PATCH', body: JSON.stringify(selected) }); setSelected(x); await refresh() }}>{t('Save author')}</button><hr /><h3>{t('Books by')} {selected.name}</h3>{books.length ? <div className="table-wrap"><table><thead><tr><th>{t('Title')}</th><th>{t('Library')}</th><th>{t('Status')}</th></tr></thead><tbody>{books.map(b => <tr key={`${b.libraryName}-${b.id}`}><td>{b.title}</td><td>{b.libraryName}</td><td>{t(capitalizeStatus(b.status))}</td></tr>)}</tbody></table></div> : <p className="muted">{t('No related books in the selected libraries.')}</p>}</section>}</div></div> }

function CategoriesPage({ api }: { api: Api }) { const { t } = useI18n(); const [categories, setCategories] = useState<Category[]>([]); const [selected, setSelected] = useState<Category | null>(null); const [books, setBooks] = useState<Book[]>([]); const [query, setQuery] = useState(''); const [view, setView] = useState<'cards' | 'table'>('cards'); const refresh = async () => setCategories((await api('/categories')).items); useEffect(() => { void refresh() }, []); const choose = async (c: Category) => { setSelected(c); const source: LibraryInfo[] = (await api('/libraries')).items || []; const all: Book[] = []; for (const l of source) { const p = await api(`/libraries/${l.id}/books`); all.push(...p.items.filter((b: Book) => b.categoryId === c.id).map((b: Book) => ({ ...b, libraryName: l.name }))) } setBooks(all) }; const visible = categories.filter(c => c.name.toLowerCase().includes(query.toLowerCase())); return <div><section className="toolbar card"><input value={query} onChange={e => setQuery(e.target.value)} placeholder={t('Search categories...')} /><div className="view-toggle"><button className={view === 'cards' ? 'active' : ''} onClick={() => setView('cards')}>▦</button><button className={view === 'table' ? 'active' : ''} onClick={() => setView('table')}>☷</button></div></section><div className="split"><section>{view === 'cards' ? visible.map(c => <button className="card list-card" key={c.id} onClick={() => void choose(c)}><strong>{c.name}</strong></button>) : <div className="card table-wrap"><table><thead><tr><th>{t('Category')}</th></tr></thead><tbody>{visible.map(c => <tr key={c.id} onClick={() => void choose(c)}><td>{c.name}</td></tr>)}</tbody></table></div>}</section>{selected && <section className="card panel"><h2>{t('Edit category')}</h2><label>{t('Name')}<input value={selected.name} onChange={e => setSelected({ ...selected, name: e.target.value })} /></label><button className="primary" onClick={async () => { const x = await api(`/categories/${selected.id}`, { method: 'PATCH', body: JSON.stringify(selected) }); setSelected(x); await refresh() }}>{t('Save category')}</button><hr /><h3>{t('Books in')} {selected.name}</h3>{books.length ? <div className="table-wrap"><table><thead><tr><th>{t('Title')}</th><th>{t('Author')}</th><th>{t('Library')}</th><th>{t('Status')}</th></tr></thead><tbody>{books.map(b => <tr key={`${b.libraryName}-${b.id}`}><td>{b.title}</td><td>{b.author || '-'}</td><td>{b.libraryName}</td><td>{t(capitalizeStatus(b.status))}</td></tr>)}</tbody></table></div> : <p className="muted">{t('No related books in the selected libraries.')}</p>}</section>}</div></div> }

function ProfilePage({ api, profile, mode, onSaved }: { api: Api; profile: Profile; mode: 'local' | 'aws'; onSaved: (p: Profile) => void }) { const { t, setLanguage } = useI18n(); const [p, setP] = useState(profile); const [current, setCurrent] = useState(''); const [next, setNext] = useState(''); const [msg, setMsg] = useState(''); return <section className="card panel account-panel"><h2>{t('Personal data')}</h2><label>{t('Email')}<input disabled value={p.email} /></label><label>{t('Name')}<input value={p.name || ''} onChange={e => setP({ ...p, name: e.target.value })} /></label><div className="form-row"><label>{t('Country')}<input value={p.country || ''} onChange={e => setP({ ...p, country: e.target.value })} /></label><label>{t('Birth date')}<input type="date" value={p.birthDate || ''} onChange={e => setP({ ...p, birthDate: e.target.value })} /></label></div><label>{t('Preferred language')}<select value={p.preferredLanguage || 'en'} onChange={e => setP({ ...p, preferredLanguage: e.target.value as Language })}>{(Object.keys(LANGUAGE_LABELS) as Language[]).map(code => <option key={code} value={code}>{LANGUAGE_LABELS[code]}</option>)}</select></label><button className="primary" onClick={async () => { const x = await api('/me', { method: 'PATCH', body: JSON.stringify(p) }); onSaved(x); if (x.preferredLanguage) setLanguage(x.preferredLanguage); setMsg(t('Personal data saved.')) }}>Save personal data</button><hr /><h2>{t('Password')}</h2>{mode === 'local' ? <><label>{t('Current password')}<input type="password" value={current} onChange={e => setCurrent(e.target.value)} /></label><label>{t('New password')}<input type="password" minLength={8} value={next} onChange={e => setNext(e.target.value)} /></label><button className="secondary" onClick={async () => { await api('/me/password', { method: 'POST', body: JSON.stringify({ currentPassword: current, newPassword: next }) }); setCurrent(''); setNext(''); setMsg(t('Password updated.')) }}>{t('Update password')}</button></> : <p className="muted">{t('Password changes are managed securely by Amazon Cognito.')}</p>}{msg && <div className="success">{msg}</div>}</section> }

function createLocalApi(base: string, session: LocalSession): Api { return async (path, init = {}) => { const h = new Headers(init.headers); h.set('Authorization', `Bearer ${session.accessToken}`); if (init.body) h.set('Content-Type', 'application/json'); const r = await fetch(base + path, { ...init, headers: h }); if (r.status === 204) return null; const p = await r.json().catch(() => ({})); if (!r.ok) throw new Error(p.error || 'Request failed'); return p } }
function normalizeLocalSession(p: any): LocalSession { return { accessToken: p.accessToken, refreshToken: p.refreshToken, expiresAt: Date.now() + Number(p.expiresIn || 3600) * 1000, user: p.user } }
function loadLocalSession() { try { const x = localStorage.getItem(LOCAL_SESSION_KEY); return x ? JSON.parse(x) as LocalSession : null } catch { return null } }
function persistLocalSession(s: LocalSession) { localStorage.setItem(LOCAL_SESSION_KEY, JSON.stringify(s)) }
function capitalizeStatus(value: string) { return value ? value.charAt(0).toUpperCase() + value.slice(1) : value }
function languageLabel(value?: string) { const labels: Record<string, string> = { en: 'English', es: 'Español', pt: 'Português', fr: 'Français', de: 'Deutsch' }; return labels[value || ''] || value || '-' }
function formatDisplayDate(value?: string) { if (!value) return '-'; const [y, m, d] = value.slice(0, 10).split('-'); if (!d) return value; return `${d}/${m}/${y}` }
function Landing({ onLogin, label }: { onLogin: () => void; label: string }) { const { t } = useI18n(); return <main className="center page-shell"><section className="card auth-card"><div className="brand-mark">L</div><p className="eyebrow">BABLEX</p><h1>{t('Your books, one simple place.')}</h1><p className="muted">{t('Private collections with optional library sharing.')}</p><button className="primary full" onClick={onLogin}>{t(label)}</button></section></main> }

bootstrap().catch(err => { console.error(err); const root = document.getElementById('root'); if (root) root.innerHTML = `<main class="center page-shell"><section class="card auth-card"><h1>Unable to start</h1><p class="muted">${String(err)}</p></section></main>` })
